head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setColumnVisibleColumn]<br/>Body Column 정보를 사용하여 특정 Column 에 바인딩된 특정 아이템의 표시 여부를 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터는 Row 가 MultiLine 이어도 모든 Column 은 고유의 인덱스값을 갖습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Body Row MultiLine 구성)
//  - gBody 에 <w2:row> 2개 -> 한 데이터 Row 가 2 Line 으로 표시
//  - 1줄 = col1(인덱스0:text) / col2(인덱스1:text)
//  - 2줄 = col3(인덱스2:text) / col4(인덱스3:select, DataList dlt_grade 바인딩)
//  - Row 가 MultiLine 이어도 col1~col4 는 각각 고유 인덱스(0~3) 를 가짐
//  - select 컬럼(col4) 은 2줄 마지막의 고유 누적 인덱스 3 -> 이 인덱스로 setColumnVisibleColumn 호출
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof dlt_grade !== 'undefined') {
        $p.data.remove("dlt_grade");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // MultiLine 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Body 가 MultiLine(2줄). 한 데이터 Row 가 2줄에 걸쳐 표시됨. 1줄 col1(0:text)/col2(1:text), 2줄 col3(2:text)/col4(3:select) 고유 인덱스. select 컬럼(col4) 은 2줄 마지막에 위치하며 dlt_grade(label/value/visible_info) 바인딩. 데이터 Row 3개.\n[절차] columnInfo(0~3) 선택 후 (setColumnVisibleColumn 실행) -> 선택 인덱스 컬럼에 대해 setColumnVisibleColumn(인덱스, visible_info, F,0) 호출.\n[확인] MultiLine(2줄) 이어도 2줄 마지막 select 컬럼은 고유 누적 인덱스 3 으로 정확히 지목됨. 인덱스 3 호출 시 dlt_grade 의 visible_info 가 F 또는 0 인 아이템(B등급/D등급) 이 itemArr 에서 제외됨. text 컬럼(0/1/2) 호출은 select 아님이라 미동작."', '', 'label1');

    // select 컬럼 옵션용 DataList (label/value/visible_info) 동적 생성
    //  - visible_info 가 F 또는 0 인 아이템(B등급/D등급) 은 setColumnVisibleColumn(.., "visible_info", "F,0") 시 숨김
    let strGrade = '';
    strGrade += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_grade" baseNode="list" repeatNode="map">';
    strGrade += '<w2:columnInfo>';
    strGrade += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strGrade += '<w2:column id="value" name="value" dataType="text"></w2:column>';
    strGrade += '<w2:column id="visible_info" name="visible_info" dataType="text"></w2:column>';
    strGrade += '</w2:columnInfo>';
    strGrade += '<w2:data use="true"></w2:data>';
    strGrade += '</w2:dataList>';
    $p.data.create(strGrade);
    dlt_grade.setJSON([
        { "label": "A등급", "value": "A", "visible_info": "T" },
        { "label": "B등급", "value": "B", "visible_info": "F" },
        { "label": "C등급", "value": "C", "visible_info": "1" },
        { "label": "D등급", "value": "D", "visible_info": "0" }
    ], false);

    // dataList 생성 + 초기값 바인딩 (col1~col4)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "서울 강남점", "col2": "1250", "col3": "김영업", "col4": "A" },
        { "col1": "부산 해운대점", "col2": "980", "col3": "이판매", "col4": "B" },
        { "col1": "대구 수성점", "col2": "1430", "col3": "박상담", "col4": "C" }
    ]);

    // Property 설정은 createCList 공통 함수 사용 (편집모드 진입 위해 editable)
    let properties = {
        dataList: "data:dlt_bind",
        editable: "true"
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // target 생성 (Body Row MultiLine : gBody 에 <w2:row> 2개)
    //  - 1줄 : col1(0:text) / col2(1:select, dlt_grade 바인딩)
    //  - 2줄 : col3(2:text) / col4(3:text)
    //  - Row 가 MultiLine 이어도 모든 Column 은 고유 인덱스(0~3)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" id="" style="width:560px;height:360px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol1" value="지점명"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol2" value="매출(만원)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol3" value="담당자"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="등급(select)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    // index 0 : col1 (text)
    strTarget += '<w2:column width="280" inputType="text" id="col1" dataList="col1"></w2:column>';
    // index 1 : col2 (text)
    strTarget += '<w2:column width="*" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    // index 2 : col3 (text)
    strTarget += '<w2:column width="280" inputType="text" id="col3" dataList="col3"></w2:column>';
    // index 3 : col4 (select) - DataList(dlt_grade) 바인딩 itemset -> setColumnVisibleColumn 대상 (2줄 마지막, MultiLine 고유 인덱스 3)
    strTarget += '<w2:column width="*" inputType="select" id="col4" dataList="col4">';
    strTarget += '<w2:choices><w2:itemset nodeset="data:dlt_grade"><w2:label ref="label"></w2:label><w2:value ref="value"></w2:value></w2:itemset></w2:choices>';
    strTarget += '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// select 컬럼의 현재 아이템 목록(표시/숨김) 을 읽어 반환
//  - WebSquare select 셀은 편집모드로 td 진입 후 cellInfo.select.itemArr 로 아이템 확인
//  - setColumnVisibleColumn 으로 숨김 처리된 아이템은 itemArr 항목에 _hidden 플래그가 부여됨
//  - 표시 아이템 / 숨김 아이템 을 각각 분류하여 반환
scwin.readItemInfo = function (colIndex) {
    let td = document.querySelector("td[id*='target1_cell_0_" + colIndex + "']");
    if (!td) { return null; }
    target1.setEditMode(td);
    let ci = target1.getCellInfo(colIndex);
    let sel = (ci && ci.select) ? ci.select : null;
    if (!sel || !sel.itemArr) { return null; }
    let visible = [];
    let hidden = [];
    for (let i = 0; i < sel.itemArr.length; i++) {
        let it = sel.itemArr[i];
        if (it._hidden) {
            hidden.push(it.label);
        } else {
            visible.push(it.label);
        }
    }
    return { "visible": visible, "hidden": hidden };
}

// [실행] setColumnVisibleColumn : 선택한 컬럼(고유 누적 인덱스) 에 대해 호출
//  - select 컬럼(2줄 마지막, 인덱스 3) 호출 시 dlt_grade 의 visible_info 가 "F" 또는 "0" 인 아이템이 리스트에서 숨김(_hidden) 처리됨
//  - MultiLine 이어도 col1~col4 는 고유 인덱스(0~3) -> 2줄 마지막 select 컬럼은 고유 인덱스 3 으로 정확히 지목됨
scwin.btn_setVisibleColumn_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());
    let colID = target1.getColumnID(columnInfo);   // MultiLine Row 에서도 col1~col4 는 고유 인덱스(0~3)
    let inputType = target1.getCellInfo(columnInfo).options.inputType;

    target1.setColumnVisibleColumn(columnInfo, "visible_info", "F,0");

    let msg = "setColumnVisibleColumn(" + columnInfo + ", 'visible_info', 'F,0') 실행 -> [고유 인덱스 " + columnInfo + " / " + colID + " / inputType=" + inputType + "]";

    let info = scwin.readItemInfo(columnInfo);
    if (info === null) {
        msg += "\n해당 컬럼은 select(DataList 바인딩) 아님 -> 적용 대상 아이템 없음 (미동작)";
    } else {
        msg += "\n표시 아이템 : " + info.visible.join(', ');
        msg += "\n숨김 아이템(visible_info 가 F 또는 0) : " + info.hidden.join(', ');
    }

    wf_body_bottom.getObj("scwin").setReturnValue(msg);
}
